interface Step {
  name: string;
  ok: boolean;
}

function pipelineReport(steps: Step[]): string {
  var okCount: number = 0;
  var failCount: number = 0;
  var first: string = 'none';
  for (var i = 0; i < steps.length; i++) {
    if (steps[i].ok) {
      okCount += 1;
    } else {
      failCount += 1;
      if (first === 'none') {
        first = steps[i].name;
      }
    }
  }
  return 'ok=' + okCount + ',failed=' + failCount + ',first=' + first;
}

